-- =====================================================
-- AERORESILIENCE - 95_export_for_powerbi.sql
-- Exports the 11 star-schema tables Power BI needs as CSV files into one Snowflake stage,
-- in one go. ThAERORESILIENCE.PUBLIC.POWERBI_EXPORTAERORESILIENCE.PUBLIC.POWERBI_EXPORTAERORESILIENCE.PUBLIC.POWERBI_EXPORTAERORESILIENCE.PUBLIC.POWERBI_EXPORTen download them from the stage (Catalog -> AERORESILIENCE -> PUBLIC ->
-- Stages -> POWERBI_EXPORT). Select EVERYTHING below and click Run.
-- Role ACCOUNTADMIN, warehouse AERO_WH.
-- =====================================================
USE ROLE ACCOUNTADMIN;
USE SECONDARY ROLES ALL;
USE WAREHOUSE AERO_WH;

-- A stage = a file folder inside Snowflake. DIRECTORY lets Snowsight list and download the files.
CREATE STAGE IF NOT EXISTS AERORESILIENCE.PUBLIC.POWERBI_EXPORT
    DIRECTORY = (ENABLE = TRUE)
    COMMENT = 'CSV exports of the dbt marts for Power BI';

-- One reusable CSV format: header row, quotes around text, empty string for NULLs, no zip
CREATE OR REPLACE FILE FORMAT AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT
    TYPE = CSV
    COMPRESSION = NONE
    FIELD_OPTIONALLY_ENCLOSED_BY = '"'
    NULL_IF = ();

-- COPY INTO @stage = UNLOAD (the reverse of loading). SINGLE = one file per table.
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/FACT_FLIGHT.csv             FROM AERORESILIENCE.DBT_DEV_MARTS.FACT_FLIGHT             FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/FACT_FLIGHT_DELAY.csv       FROM AERORESILIENCE.DBT_DEV_MARTS.FACT_FLIGHT_DELAY       FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/FACT_BAG_JOURNEY.csv        FROM AERORESILIENCE.DBT_DEV_MARTS.FACT_BAG_JOURNEY        FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/FACT_PASSENGER_JOURNEY.csv  FROM AERORESILIENCE.DBT_DEV_MARTS.FACT_PASSENGER_JOURNEY  FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/FACT_INVENTORY_SNAPSHOT.csv FROM AERORESILIENCE.DBT_DEV_MARTS.FACT_INVENTORY_SNAPSHOT FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/FACT_MAINTENANCE_EVENT.csv  FROM AERORESILIENCE.DBT_DEV_MARTS.FACT_MAINTENANCE_EVENT  FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/DIM_AIRLINE.csv             FROM AERORESILIENCE.DBT_DEV_MARTS.DIM_AIRLINE             FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/DIM_AIRPORT.csv             FROM AERORESILIENCE.DBT_DEV_MARTS.DIM_AIRPORT             FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/DIM_DATE.csv                FROM AERORESILIENCE.DBT_DEV_MARTS.DIM_DATE                FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/DIM_DELAY_CODE.csv          FROM AERORESILIENCE.DBT_DEV_MARTS.DIM_DELAY_CODE          FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;
COPY INTO @AERORESILIENCE.PUBLIC.POWERBI_EXPORT/DIM_PART.csv                FROM AERORESILIENCE.DBT_DEV_MARTS.DIM_PART                FILE_FORMAT = (FORMAT_NAME = 'AERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT') HEADER = TRUE SINGLE = TRUE OVERWRITE = TRUE MAX_FILE_SIZE = 268435456;

-- Refresh the stage's file list, then show the 11 files and their sizes (expect 11 rows)
ALTER STAGE AERORESILIENCE.PUBLIC.POWERBI_EXPORT REFRESH;
SELECT relative_path, size, last_modified
FROM DIRECTORY(@AERORESILIENCE.PUBLIC.POWERBI_EXPORT)
ORDER BY relative_path;AERORESILIENCE.PUBLIC.POWERBI_EXPORTAERORESILIENCE.PUBLIC.CSV_EXPORT_FORMAT